import json, pathlib
OUT = pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round77/predictions")
OUT.mkdir(parents=True, exist_ok=True)
def W(cid, pred, basis, conf, trig=None):
    if trig is None:
        trig = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    rec = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf, "trigger": trig}
    (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}
def LY(trad, extra):
    return f"tradition: {trad}\nsystems_used: liuyao\n" + extra
STD = "列面:主问面已断;余面题面未载或有面无据不报。锚点转应核:卦名/支数取直读,转应已列而舍,理由为盘面用神链已定主向。断项过闸:主断->用神指代链->盘面触发,保留;无具体断项删去。动化定性核对:动化方向见下;反转条件:终局反转信号三类须全立才翻转,本例未全立故不翻。应期(k)先定档再(h)三路:冲实/填实/逢值逐路列后取一舍二。R61核:应期二路复推见下;断项粒度核:处所/数量类断项支撑<2者已降为方位/等级带或删去,方向主断不降档。"

